function i_lim_out = mfun_gfl_current_limiter(i_in, p)
%MFUN_GFL_CURRENT_LIMITER Block CurrentLimiter of the control system.
%   CurrentLimiter of motulator. Generated by motulator_export from the MATLAB port of
%   motulator and called by the MATLAB Function block of the library of motulator, whose
%   folder motulator.setup adds to the MATLAB path. The parameters are the fields of the
%   struct p (from the mask, [] as NaN).
i = complex_in(i_in);
i_lim = current_limiter(p.i_max, i);
i_lim_out = complex_out(i_lim);
end

function z = complex_in(u)
%COMPLEX_IN Complex number from a signal [real part; imaginary part].
z = complex(u(1), u(2));
end

function y = complex_out(z)
%COMPLEX_OUT Signal [real part; imaginary part] of a complex number.
y = [real(z); imag(z)];
end

function i = current_limiter(i_max, i)
%CURRENT_LIMITER Limit the magnitude of a current vector to i_max (CurrentLimiter).
if abs(i) > i_max
    i = i_max*i/abs(i);
end
end
